private fun getSecretKey(alias: String): SecretKey {
    return keyCache[alias] ?: (keyStore.getEntry(alias, null) as? KeyStore.SecretKeyEntry)?.secretKey?.also {
        keyCache[alias] = it
    } ?: createKey(alias)
}

